-  if (is_closure) {
+  if (is_closure || !needed) {
     return (none, false);
   }
   let idx: i32 = -1;
@@ -9004,8 +9014,8 @@ function in_place_array_write(a: ast.StmtAssign, env: Env): boolean {
   if (av.view || interpheap.get(av.store).words.len() > 0) {
     return false;
   }
-  let (fd, known) = call_target("with", true, false, value, env);
-  let (fd2, known2) = call_target("append", true, false, value, env);
+  let (fd, known) = call_target("with", true, false, value, env, true);
+  let (fd2, known2) = call_target("append", true, false, value, env, true);
